<?php
declare(strict_types=1);
namespace Sentinel\Tests\Unit\Services;
use PDO;use PHPUnit\Framework\TestCase;use Sentinel\Core\Config;use Sentinel\Core\Database;use Sentinel\Core\HttpException;use Sentinel\Core\RuntimeContext;use Sentinel\Repositories\AuditRepository;use Sentinel\Repositories\IncidentRepository;use Sentinel\Services\AuditService;use Sentinel\Services\IncidentManagementService;
final class IncidentManagementServiceTest extends TestCase {private function service():array{$db=new Database(new Config(['database'=>[]]),static fn():PDO=>new PDO('sqlite::memory:',null,null,[PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]));foreach(['sites (site_id INTEGER,company_id INTEGER)','employees (employee_id INTEGER,company_id INTEGER)','users (user_id INTEGER,company_id INTEGER)','shift_assignments (shift_assignment_id INTEGER,company_id INTEGER,employee_id INTEGER,site_id INTEGER,deleted_at TEXT)','employee_assignments (employee_assignment_id INTEGER,company_id INTEGER,employee_id INTEGER)','patrol_routes (patrol_route_id INTEGER,company_id INTEGER,site_id INTEGER)','patrol_sessions (patrol_session_id INTEGER,company_id INTEGER,employee_assignment_id INTEGER,patrol_route_id INTEGER,deleted_at TEXT)','incidents (incident_id INTEGER PRIMARY KEY AUTOINCREMENT,incident_uuid TEXT,company_id INTEGER,site_id INTEGER,employee_id INTEGER,reporter_user_id INTEGER,shift_assignment_id INTEGER,patrol_session_id INTEGER,incident_number TEXT,incident_type TEXT,incident_category TEXT,severity TEXT,status TEXT,occurred_at TEXT,reported_at TEXT,description TEXT,actions_taken TEXT,resolution TEXT,created_by_user_id INTEGER,updated_by_user_id INTEGER,closed_at TEXT,created_at TEXT,updated_at TEXT,deleted_at TEXT,UNIQUE(company_id,incident_number))','audit_logs (audit_log_id INTEGER PRIMARY KEY,company_id INTEGER,user_id INTEGER,entity_name TEXT,entity_id TEXT,action_name TEXT,action_status TEXT,ip_address TEXT,user_agent TEXT,old_values TEXT,new_values TEXT,metadata TEXT)']as$sql)$db->execute('CREATE TABLE '.$sql);$db->execute('INSERT INTO sites VALUES (3,101),(4,202)');$db->execute('INSERT INTO employees VALUES (6,101),(7,101),(8,202)');$db->execute('INSERT INTO users VALUES (9,101),(10,202)');$db->execute('INSERT INTO shift_assignments VALUES (11,101,7,3,NULL)');$context=new RuntimeContext();$context->setTenantId(101);$context->setUser('9');return[new IncidentManagementService(new IncidentRepository($db,$context),$context,new AuditService(new AuditRepository($db,$context),$context)),$db];}
public function testIncidentCreateLifecycleRelationshipsAndAuditAreSafe():void{[$service,$db]=$this->service();try{$service->createIncident(['site_id'=>4,'incident_type'=>'SECURITY','incident_category'=>'ACCESS','occurred_at'=>'2026-09-14 08:00:00','description'=>'foreign']);self::fail();}catch(HttpException $e){self::assertSame(404,$e->statusCode());}$incident=$service->createIncident(['site_id'=>3,'employee_id'=>7,'reporter_user_id'=>9,'shift_assignment_id'=>11,'incident_type'=>'SECURITY','incident_category'=>'ACCESS','severity'=>'HIGH','occurred_at'=>'2026-09-14 08:00:00','reported_at'=>'2026-09-14 08:05:00','description'=>'Operational detail']);self::assertSame('OPEN',$incident['status']);$investigating=$service->updateIncident((string)$incident['incident_id'],['status'=>'INVESTIGATING']);self::assertSame('INVESTIGATING',$investigating['status']);$resolved=$service->updateIncident((string)$incident['incident_id'],['status'=>'RESOLVED','resolution'=>'Contained']);$closed=$service->updateIncident((string)$incident['incident_id'],['status'=>'CLOSED','closed_at'=>'2026-09-14 10:00:00','resolution'=>'Contained']);self::assertSame('CLOSED',$closed['status']);try{$service->updateIncident((string)$incident['incident_id'],['status'=>'OPEN']);self::fail();}catch(HttpException $e){self::assertSame(422,$e->statusCode());}$audit=$db->fetch('SELECT new_values FROM audit_logs WHERE audit_log_id=1');self::assertStringNotContainsString('Operational detail',(string)$audit['new_values']);}
public function testIncidentInputRejectsTenantOverrideAndInvalidTimestamp():void{[$service]=$this->service();foreach([['company_id'=>202],['site_id'=>3,'incident_type'=>'S','incident_category'=>'C','occurred_at'=>'bad','description'=>'x'],['site_id'=>3,'employee_id'=>7,'shift_assignment_id'=>11,'incident_type'=>'S','incident_category'=>'C','occurred_at'=>'2026-09-14 09:00:00','reported_at'=>'2026-09-14 08:00:00','description'=>'x']]as$input){try{$service->createIncident($input);self::fail();}catch(HttpException $e){self::assertSame(422,$e->statusCode());}}}
public function testIncidentRejectsShiftEmployeeMismatch():void{[$service]=$this->service();try{$service->createIncident(['site_id'=>3,'employee_id'=>6,'shift_assignment_id'=>11,'incident_type'=>'S','incident_category'=>'C','occurred_at'=>'2026-09-14 08:00:00','description'=>'x']);self::fail();}catch(HttpException $e){self::assertSame(422,$e->statusCode());}}}